const body = $input.first().json.body || $input.first().json;

// ── Article mode ──
const validModes = ['player_article','game_recap','event_standouts','team_story','recruiting_report','recruiting_summary'];
const rawMode = (body.mode || 'player_article').trim().toLowerCase().replace(/[\s-]/g,'_');
const normalizedMode = rawMode === 'recruiting_summary' ? 'recruiting_report' : rawMode;
const mode = validModes.includes(normalizedMode) ? normalizedMode : 'player_article';
const modeLabels = {
  player_article:    'Player Feature Article',
  game_recap:        'Game Recap',
  event_standouts:   'Event Standouts',
  team_story:        'Team Story',
  recruiting_report: 'Recruiting Report'
};

// ── Style preset ──
const validPresets = [
  'Neutral Reporter','Recruiting Analyst','Scouting Breakdown','Event Recap',
  'Player Spotlight','High-Energy Feature','Feature Story','Professional Media','Shortform Social',
  'Development-Focused','Coach/Recruiter Brief'
];
const rawPreset = (body.style_preset || 'Neutral Reporter').trim();
const stylePreset = validPresets.includes(rawPreset) ? rawPreset : 'Neutral Reporter';

// ── Tone ──
const validTones = ['analytical','narrative','energetic','neutral','technical','inspirational'];
const tone = validTones.includes((body.tone||'').toLowerCase()) ? body.tone.toLowerCase() : 'analytical';

// ── Audience ──
const validAudiences = ['general_public','college_recruiters','coaches','parents_players','media_press','social_media'];
const rawAud = (body.audience||'general_public').toLowerCase().replace(/[\s-]/g,'_');
const audience = validAudiences.includes(rawAud) ? rawAud : 'general_public';
const audienceLabels = {
  general_public:   'General Sports Audience',
  college_recruiters:'College Recruiters',
  coaches:          'Coaches & Staff',
  parents_players:  'Parents & Players',
  media_press:      'Media & Press',
  social_media:     'Social Media'
};

// ── Confidence level ──
const validConf = ['high','moderate','measured','cautious'];
const confidence = validConf.includes((body.confidence||'').toLowerCase()) ? body.confidence.toLowerCase() : 'moderate';

// ── Primary angle ──
const validAngles = ['breakout_performance','defensive_impact','clutch_performance','floor_general_leadership','shooting_showcase','two_way_player'];
const rawAngle = (body.primary_angle || 'breakout_performance').toLowerCase().replace(/[\s-]/g,'_');
const primaryAngle = validAngles.includes(rawAngle) ? rawAngle : 'breakout_performance';

// ── Word count ──
const rawWC = parseInt(body.word_count) || 350;
const wordCount = Math.min(Math.max(rawWC, 80), 800);

// ── Core content fields ──
const playerName     = (body.player_name     || '').trim();
const position       = (body.position        || '').trim();
const team           = (body.team            || '').trim();
const ageGrade       = (body.age_grade       || '').trim();
const eventName      = (body.event_name      || '').trim();
const evalNotes      = (body.evaluator_notes || '').trim();
const gameNotes      = (body.game_notes      || '').trim();
const teamNotes      = (body.team_notes      || '').trim();
const standoutTags   = Array.isArray(body.standout_tags) ? body.standout_tags : [];
const sliders        = body.sliders && typeof body.sliders === 'object' ? body.sliders : {};
const styleSample    = (body.style_sample    || '').trim();
const styleSampleUrl = (body.style_sample_url || '').trim();
const serpContext = (body.serp_context || body.research_snippets || '').trim();
const validSpines = ['stakes','timeline','matchup','identity','legacy','injury_subplot'];
const rawSpine = (body.story_spine || 'stakes').trim().toLowerCase().replace(/[\s-]/g,'_');
const storySpine = validSpines.includes(rawSpine) ? rawSpine : 'stakes';
const momentAnchor1 = (body.moment_anchor_1 || '').trim();
const momentAnchor2 = (body.moment_anchor_2 || '').trim();
const momentAnchor3 = (body.moment_anchor_3 || '').trim();
const statLine = (body.stat_line || '').trim();
const verifiedFacts = (body.verified_facts || '').trim();
const quote1 = (body.quote_1 || '').trim();
const quote2 = (body.quote_2 || '').trim();
const quote3 = (body.quote_3 || '').trim();
const espnDepthMode = body.espn_depth_mode === true || body.espn_depth_mode === 'true';
const clampV = (x) => Math.min(10, Math.max(1, parseInt(x, 10) || 6));
const voicePunch = clampV(body.voice_punch);
const voiceAnalyticsDensity = clampV(body.voice_analytics_density);
const voiceSceneDetail = clampV(body.voice_scene_detail);
const pubName        = (body.publication_name|| 'SportsPilot').trim();
const sectionRewrite = (body.section_rewrite || '').trim(); // headline / intro / body / closing
const rewriteContent = (body.rewrite_content || '').trim(); // text to rewrite

// ── Validation: require some content ──
const hasContent = evalNotes.length > 10 || gameNotes.length > 10 || teamNotes.length > 10;
if (!hasContent) throw new Error('evaluator_notes, game_notes, or team_notes is required');

// ── Session ID ──
const sessionId = 'CAI-' + Date.now() + '-' + Math.random().toString(36).substring(2,8).toUpperCase();

return [{
  json: {
    sessionId, mode, modeLabel: modeLabels[mode],
    stylePreset, tone, audience, audienceLabel: audienceLabels[audience],
    confidence, primaryAngle, wordCount,
    playerName, position, team, ageGrade, eventName,
    evalNotes, gameNotes, teamNotes,
    standoutTags, sliders, styleSample, styleSampleUrl, serpContext, pubName,
    sectionRewrite, rewriteContent,
    isRewrite: sectionRewrite.length > 0,
    timestamp: new Date().toISOString()
  }
}];

const d = $input.first().json;

// ── Slider summary for prompt ──
function sliderSummary(sliders) {
  if (!sliders || !Object.keys(sliders).length) return '';
  const lines = Object.entries(sliders).map(([k,v]) => {
    const label = k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
    const bar = '█'.repeat(Math.round(v/10*10)).padEnd(10,'░');
    return `  ${label.padEnd(20)} ${bar} ${v}/10`;
  });
  return '\nEVALUATION SLIDERS:\n' + lines.join('\n');
}

// ── Style sample instruction ──
const styleInstruction = d.styleSample && d.styleSample.length > 50
  ? `\nSTYLE SAMPLE — ADOPT THIS WRITER'S VOICE:\nThe following is a sample of writing from the target publication/author. Analyse the vocabulary, sentence rhythm, paragraph length, metaphor density, and structural choices. Mirror this style precisely in your article — do NOT copy sentences, only adopt the voice:\n---\n${d.styleSample.slice(0,1200)}\n---`
  : '';

// ── Confidence calibration ──
const confGuides = {
  high:     'Write with confident, assertive language. Use strong declarative statements. Do not hedge projections.',
  moderate: 'Balance confidence with appropriate qualification. Avoid superlatives. Let evidence speak.',
  measured: 'Use measured, evidence-anchored language. Qualify projections clearly. Avoid speculation.',
  cautious: 'Write conservatively. Every claim must be directly supported by the evaluator notes provided.'
};

// ── Audience calibration ──
const audGuides = {
  general_public:    'Write for a broad sports fan audience. Focus on compelling narrative and entertainment. Make the reader feel the moment.',
  college_recruiters:'Write for college coaches and recruiting staff. Lead with projectable skills, coachability, intangibles, and competitive fit. Be efficient but thorough — coaches read fast.',
  coaches:           'Write for coaching professionals. Use technical terminology. Include tactical observations, positioning notes, and system fit.',
  parents_players:   'Write in an encouraging, accessible tone. Celebrate effort and character alongside performance. Avoid overly technical language.',
  media_press:       'Write in polished media-standard prose. Think ESPN or The Athletic. Headline-friendly, quotable sentences, vivid specific moments.',
  social_media:      'Write punchy, high-energy shortform. Designed for sharing. Build around the single most shareable moment or stat.'
};

// ── Primary angle calibration ──
const angleGuides = {
  breakout_performance:      'Center the story around a breakout or statement-level performance and why it matters.',
  defensive_impact:          'Prioritize defensive possessions, containment, effort habits, and two-way value.',
  clutch_performance:        'Emphasize late-game execution, decision-making under pressure, and closing possessions.',
  floor_general_leadership:  'Highlight leadership, pace control, organization, and decision quality as a floor general.',
  shooting_showcase:         'Focus on shot creation, shot quality, range, mechanics, and scoring efficiency.',
  two_way_player:            'Balance offensive creation with defensive responsibility and impact on both ends.'
};

// ── Style preset instructions ──
const presetGuides = {
  'Neutral Reporter':      'Objective, factual, journalistic. No opinion unless clearly attributed. Think AP wire with heart.',
  'Recruiting Analyst':    'Data-informed, projection-focused, coach-facing. Clinical but readable. Every sentence earns its place.',
  'Scouting Breakdown':    'Technical, structured, category-driven. Think scouting report prose — specific, observational, layered.',
  'Event Recap':           'Chronological flow, game-moment highlights, competitive context. Build tension and resolution.',
  'Player Spotlight':      'Narrative-first, character-driven. Bring the reader into the moment with the player. Celebratory but grounded.',
  'High-Energy Feature':   'Bold, punchy, fast-paced. Vivid verbs. Short punchy sentences mixed with longer builds. Exclamation of excellence.',
  'Feature Story':         'Narrative-driven and polished, blending scene setting with basketball insight and clear through-lines.',
  'Professional Media':    'Polished, broadcast-quality, publication-ready. Think The Athletic or ESPN Feature. Memorable opening lines.',
  'Shortform Social':      'Tight, punchy, shareable. 150-200 words. Built for social virality. One key hook per paragraph.',
  'Development-Focused':   'Growth-minded, forward-looking, coachable-trait emphasis. Every observation connects to a future ceiling.',
  'Coach/Recruiter Brief': 'Efficient, hierarchical, time-respecting. Front-load the most important evaluation data.'
};

// ── DETAILED MODE-SPECIFIC STRUCTURE GUIDES (ESPN-caliber) ──
const modeStructures = {
  player_article: `ARTICLE STRUCTURE — Follow this precisely:

1. HEADLINE: Specific, vivid, captures the player's defining quality. Not generic. Example style: "The Floor General Nobody Saw Coming" or "Thompson's Vision Is Ahead of His Time."

2. LEDE (2-3 sentences, ~60 words): Open with the most memorable single moment or quality. Drop the reader into a specific scene or game situation. Make them want to read the next paragraph.

3. PERFORMANCE NARRATIVE (3-4 paragraphs, ~180-250 words total):
   - Paragraph 1: Set the competitive context. What event, what stage, what was at stake.
   - Paragraph 2: Break down the headline performance. Use specific numbers and moments from the evaluator notes. Show, don't tell.
   - Paragraph 3: Explain WHY this performance matters — what it reveals about the player's game at a deeper level.
   - Paragraph 4 (optional): A counterpoint or complexity — the honest observation that adds credibility.

4. STANDOUT QUALITIES (2 paragraphs, ~120 words): Reference the standout tags provided. Each quality gets a specific observation from the notes that illustrates it. Avoid vague praise — anchor every claim.

5. DEVELOPMENT AREAS (1 paragraph, ~70 words): Written constructively, not negatively. Frame as "the area that separates a good player from a great one" or "the refinement that will unlock the next level."

6. PROJECTION (1-2 sentences, ~50 words): Calibrated to confidence level. Should feel earned by the evidence above. Specific about level and role — not just "has a bright future."

7. CLOSING LINE (1-2 sentences): Memorable. Should feel like the final line of a magazine feature — leaves the reader with a clear impression.

TOTAL TARGET: ${d.wordCount} words. ESPN player features average 450-700 words. Do not produce a thin article — every section must have substance.`,

  game_recap: `ARTICLE STRUCTURE — Follow this precisely:

1. HEADLINE: Captures the game's defining moment or narrative arc.

2. GAME LEDE (2-3 sentences, ~70 words): Score, teams, what was at stake, the single defining story of the game.

3. GAME NARRATIVE (4-5 paragraphs, ~250-350 words total):
   - Paragraph 1: First-half or early-game context — who established momentum and how.
   - Paragraph 2: The turning point(s). Specific plays, moments, sequences from the game notes.
   - Paragraph 3: Key performer(s) breakdown. Stats anchored in narrative — not just numbers, but what those numbers meant.
   - Paragraph 4: The closing stretch. How it was won or lost. The specific moment that decided it.
   - Paragraph 5: Character/effort observations that go beyond the box score.

4. STATISTICAL ANCHORS (woven naturally into above, not a separate list).

5. CONTEXTUAL SIGNIFICANCE (1 paragraph, ~70 words): Season implications, rivalry context, what this result means going forward.

6. CLOSING LINE: Forward-looking. Sets up the next game or storyline.

TOTAL TARGET: ${d.wordCount} words. Game recaps should feel like reading a newspaper game story — complete, vivid, and worth saving.`,

  event_standouts: `ARTICLE STRUCTURE — Follow this precisely:

1. HEADLINE: Captures the event's top story or breakout performer.

2. EVENT OVERVIEW LEDE (2-3 sentences, ~60 words): What was the event, why it mattered, and the headline story.

3. TOP PERFORMER #1 (3-4 sentences, ~120-150 words):
   Name, position, team — then: what they did, how they did it, a specific moment that defines their performance, and why it matters for their trajectory.

4. TOP PERFORMER #2 (same structure, ~120-150 words).

5. TOP PERFORMER #3 (same structure, ~120-150 words).

6. NOTABLE MENTIONS (2-3 players, 2-3 sentences each, ~100 words total): Brief but specific. Name, one defining quality, one standout moment.

7. EVENT SUMMARY (1 paragraph, ~60 words): What the event revealed about this class, this group, this level of competition. Forward-looking.

TOTAL TARGET: ${d.wordCount} words. Think ESPN's SC Next Top 25 write-ups — each player gets a real, substantive paragraph.`,

  team_story: `ARTICLE STRUCTURE — Follow this precisely:

1. HEADLINE: Team identity in one vivid phrase.

2. TEAM IDENTITY LEDE (2-3 sentences, ~70 words): Who is this team? What is their identity? What makes them different from every other team in the building?

3. DEFINING CHARACTERISTICS (2-3 paragraphs, ~180-220 words):
   - Paragraph 1: Their style of play. Specific, tactical. What do they do that others don't?
   - Paragraph 2: The chemistry and culture. What the notes say about how they operate as a unit.
   - Paragraph 3: The coaching imprint. How the staff's system shows up in the way they play.

4. KEY CONTRIBUTORS (2-3 players profiled, ~50-80 words each): Name, role, and what they specifically contribute to the team identity. Grounded in notes.

5. NARRATIVE ARC (1 paragraph, ~80 words): Is this team ascending, plateauing, or battling adversity? What is their story this season?

6. WHAT TO WATCH (1 paragraph, ~60 words): Forward-looking. What will determine how far this team goes?

7. CLOSING STATEMENT: Memorable. A line that captures the essence of this team.

TOTAL TARGET: ${d.wordCount} words.`,

  recruiting_report: `ARTICLE STRUCTURE — Follow this precisely (think ESPN Recruiting Nation standard):

1. HEADLINE: Projection-forward. "The Point Guard Built for the Modern Game" not "Good Point Guard."

2. PLAYER OVERVIEW (1 paragraph, ~80 words): Position, class/grade, physical profile, team, event. Set the baseline quickly.

3. EVALUATION SNAPSHOT (~50 words): Lead with the slider scores and standout tags translated into natural language. "A 9/10 in basketball IQ translates on film as..." Not a list — a narrative interpretation.

4. STRENGTHS — TOP 3 (3 paragraphs, ~60-80 words each):
   Each strength gets: the observation, the specific evidence from notes, and what it means at the next level.
   Format: [Strength Name] — then the supporting case. Substantive, not thin.

5. DEVELOPMENT AREAS (1-2 paragraphs, ~80-100 words): Honest and specific. The areas that scouts and coaches will probe. Written constructively but directly — this is a recruiting audience.

6. FIT PROFILE (1 paragraph, ~70 words): What system suits this player? What college/program level is realistic and why? Be specific about fit — not just "high-major potential."

7. EVALUATOR RECOMMENDATION (2-3 sentences, ~50 words): The closing verdict. Calibrated to confidence level. Should read like a scout's final note on a film session.

TOTAL TARGET: ${d.wordCount} words. Recruiting reports read like actionable intelligence — coaches should finish and know exactly what they're getting.`
};

// ── Build content block ──
const contentLines = [];
if (d.playerName) contentLines.push('Player: ' + d.playerName + (d.position ? ' — ' + d.position : '') + (d.team ? ' | ' + d.team : ''));
if (d.ageGrade)   contentLines.push('Age/Grade: ' + d.ageGrade);
if (d.eventName)  contentLines.push('Event: ' + d.eventName);
if (d.evalNotes)  contentLines.push('\nEVALUATOR NOTES (use these as the SOLE factual source — do not invent beyond these):\n' + d.evalNotes);
if (d.gameNotes)  contentLines.push('\nGAME NOTES:\n' + d.gameNotes);
if (d.teamNotes)  contentLines.push('\nTEAM NOTES:\n' + d.teamNotes);
const sliderText = sliderSummary(d.sliders);
if (sliderText)   contentLines.push(sliderText);
if (d.standoutTags.length) contentLines.push('\nSTANDOUT TAGS: ' + d.standoutTags.join(' · '));
if (d.serpContext && d.serpContext.length > 10) {
  contentLines.push('\nWEB RESEARCH SNIPPETS (SerpAPI — external context only; do NOT treat as verified facts about the player/event unless consistent with evaluator notes):\n' + d.serpContext.slice(0, 2500));
}
if (d.styleSampleUrl && d.styleSampleUrl.length > 8) {
  contentLines.push('\nSTYLE SAMPLE SOURCE URL (reference only): ' + d.styleSampleUrl);
}
const spineGuide = {
  stakes: 'Stakes — why this moment matters for standings/postseason pressure',
  timeline: 'Timeline — how recent performances set up this game',
  matchup: 'Matchup chess — counters, adjustments, and responses',
  identity: 'Identity — role, team style, and what this performance signals',
  legacy: 'Legacy/milestone framing (ONLY if supported by notes)',
  injury_subplot: 'Availability/workload subplot (ONLY if supported by notes)'
};
if (d.storySpine && spineGuide[d.storySpine]) {
  contentLines.push('\nSTORY SPINE: ' + spineGuide[d.storySpine]);
}
if (d.momentAnchor1) contentLines.push('\nMOMENT ANCHOR 1 (use as a concrete scene beat): ' + d.momentAnchor1);
if (d.momentAnchor2) contentLines.push('\nMOMENT ANCHOR 2: ' + d.momentAnchor2);
if (d.momentAnchor3) contentLines.push('\nMOMENT ANCHOR 3: ' + d.momentAnchor3);
if (d.statLine) contentLines.push('\nSTAT LINE / BOX (treat as factual anchor — do not invent beyond notes + this block):\n' + d.statLine);
if (d.verifiedFacts) contentLines.push('\nVERIFIED FACTS:\n' + d.verifiedFacts);
if (d.quote1 || d.quote2 || d.quote3) {
  const qs = [d.quote1, d.quote2, d.quote3].filter(Boolean);
  if (qs.length) contentLines.push('\nQUOTES TO WEAVE (optional):\n' + qs.join('\n---\n'));
}
if (d.espnDepthMode) {
  const targetW = Math.max(parseInt(d.wordCount,10) || 500, 650);
  contentLines.push('\nESPN-DEPTH MODE: Target at least ' + targetW + ' words. Section budgets: lede ~80–120w; stakes/nut ~120–180w; 2–3 evidence paragraphs tied to moment anchors; closing ~60–120w with a forward look. Ban vague clichés unless tied to a specific play (e.g. avoid empty "electric", "locked in", "stepped up").');
  contentLines.push('VOICE MIX (1=subtle, 10=heavy): punch ' + (d.voicePunch||6) + '/10, analytics ' + (d.voiceAnalyticsDensity||6) + '/10, scene detail ' + (d.voiceSceneDetail||6) + '/10.');
}
const contentBlock = contentLines.join('\n');

// ── Section rewrite mode ──
let systemPrompt = '';
let userPrompt   = '';

if (d.isRewrite && d.rewriteContent) {
  systemPrompt = `You are CoverageAssistAI's section rewriter. You will rewrite a specific section of a sports article.

Style preset: ${d.stylePreset}
${presetGuides[d.stylePreset]}
Primary angle: ${d.primaryAngle}
${angleGuides[d.primaryAngle] || ''}

Tone: ${d.tone} | Audience: ${d.audienceLabel} | Confidence: ${d.confidence}
${confGuides[d.confidence]}
${audGuides[d.audience]}${styleInstruction}

RULES:
- Rewrite ONLY the section provided. Return ONLY the rewritten section — no preamble, no explanation.
- Match the voice and style of the rest of the article
- Keep factual grounding — do not add uncited claims
- Make it substantially better than what was there — richer language, more specific, more vivid`;
  userPrompt = `Rewrite this ${d.sectionRewrite} section:\n\n${d.rewriteContent}`;
} else {
  systemPrompt = `You are CoverageAssistAI — the Evaluation-to-Article Engine for SportsPilotAI.

Your role: Transform structured player evaluations, game notes, and scouting data into publish-ready sports content that reads like it belongs on ESPN, The Athletic, or a professional scouting platform.

ARTICLE TYPE: ${d.modeLabel}
PUBLICATION: ${d.pubName}
STYLE PRESET: ${d.stylePreset}
${presetGuides[d.stylePreset]}
PRIMARY ANGLE: ${d.primaryAngle}
${angleGuides[d.primaryAngle] || ''}

TONE: ${d.tone}
AUDIENCE: ${d.audienceLabel}
${audGuides[d.audience]}

CONFIDENCE CALIBRATION:
${confGuides[d.confidence]}

${modeStructures[d.mode]}

ESPN / PROFESSIONAL STANDARD WRITING REQUIREMENTS:
- Every paragraph must earn its place. No filler, no padding — but also no thinness.
- Use SPECIFIC language: not "showed great athleticism" but "exploded off the first step to turn a 9-foot closeout into a layup opportunity."
- VARY sentence structure: mix short punchy sentences with longer narrative builds.
- ANCHOR statistics in narrative: not "scored 24 points" but "his 24-point effort came in waves — 12 in the first half when the game was still competitive, then 12 more in the final quarter when the game needed to be closed."
- SHOW don't tell: the slider scores and standout tags are evidence — build observations around them, don't just state them.
- Each section transition should flow naturally — the reader should never feel a structural seam.
- The closing line must be MEMORABLE. Read it last and ask: does this stay with you?

HALLUCINATION GUARD (critical):
- Every factual claim — every statistic, every moment, every observation — must trace directly to the evaluator notes, game notes, or slider scores provided.
- If the notes don't mention it, do NOT include it.
- Do not invent names, scores, opponents, plays, or biographical details.
- If notes are thin, write richly about what IS there — not about things you imagine.

OUTPUT FORMAT:
- Start directly with the headline. No preamble, no "Here is your article:", no explanation.
- Produce only the article itself.${styleInstruction}`;
  userPrompt = `SOURCE DATA (everything you write must be grounded in this):
${contentBlock}

Generate the complete, full-length ${d.modeLabel} now. Do not produce a short article — match the target word count of ${d.wordCount} words and the ESPN-caliber standard described above.`;
}

return [{ json: { ...d, system_prompt: systemPrompt, user_prompt: userPrompt } }];

const agentOut = $input.first().json;
const meta = $('Build Prompt').item.json;

const raw = (agentOut.output || agentOut.text || agentOut.response || '').trim();

// ── Extract headline (first line) ──
const lines = raw.split('\n').filter(l => l.trim());
const headline = lines[0] || '';
const body = lines.slice(1).join('\n').trim();

// ── Word count ──
const wordCount = raw.split(/\s+/).filter(Boolean).length;

// ── Detect sections for section rewrite UI ──
const sections = {
  headline: headline,
  intro: lines.length > 1 ? lines[1] : '',
  fullArticle: raw
};

return [{ json: {
  sessionId:   meta.sessionId,
  mode:        meta.mode,
  modeLabel:   meta.modeLabel,
  stylePreset: meta.stylePreset,
  tone:        meta.tone,
  audience:    meta.audience,
  confidence:  meta.confidence,
  wordCount,
  targetWordCount: meta.wordCount,
  playerName:  meta.playerName,
  team:        meta.team,
  eventName:   meta.eventName,
  isRewrite:   meta.isRewrite,
  rewriteSection: meta.sectionRewrite,
  headline,
  body,
  article:     raw,
  sections,
  hasStyleSample: meta.styleSample.length > 50,
  generatedAt: new Date().toISOString()
}}];
